selector_to_html = {"a[href=\"#what-is-resolved\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">What is resolved<a class=\"headerlink\" href=\"#what-is-resolved\" title=\"Link to this heading\">\u00b6</a></h2><p>Only one branch. Every branch of a given manifold is the same arc sized the\nsame way, so the ring is that one arc repeated \u2013 mirrored for a split\nmanifold, rotated for a multi-port one \u2013 and <a class=\"reference internal\" href=\"Manifold.html#pyskyfire.ducts.manifold.Manifold.sweep\" title=\"pyskyfire.ducts.manifold.Manifold.sweep\"><code class=\"xref py py-meth docutils literal notranslate\"><span class=\"pre\">Manifold.sweep()</span></code></a> is what\nputs the whole ring together.</p>", "a[href=\"ManifoldGeometry.html#pyskyfire.ducts.manifold.ManifoldGeometry\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.manifold.ManifoldGeometry\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.ducts.manifold.</span></span><span class=\"sig-name descname\"><span class=\"pre\">ManifoldGeometry</span></span></dt><dd><p>Resolved passage geometry along one branch.</p></dd>", "a[href=\"#branches-not-a-direction\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Branches, not a direction<a class=\"headerlink\" href=\"#branches-not-a-direction\" title=\"Link to this heading\">\u00b6</a></h2><p>A volute can only run one way, because the swirl it collects already has a\nsense. A manifold can be built either way, and the choice is a topology rather\nthan a direction.</p>", "a[href=\"Manifold.html#pyskyfire.ducts.manifold.Manifold\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.manifold.Manifold\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.ducts.manifold.</span></span><span class=\"sig-name descname\"><span class=\"pre\">Manifold</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">section</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">area_law</span></span></em>, <em class=\"sig-param\"><span class=\"keyword-only-separator o\"><abbr title=\"Keyword-only parameters separator (PEP 3102)\"><span class=\"pre\">*</span></abbr></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">branches</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">2</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">rotation</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">port</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">radius</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">tilt</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">0.0</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">n_stations</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">181</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>A distributing or collecting ring, resolved from a section and a law.</p><p class=\"rubric\">Notes</p><p>Geometry is resolved on construction and carries no operating point, so one\nmanifold can be reported at several mass flows.</p></dd>", "a[href=\"Manifold.html#pyskyfire.ducts.manifold.Manifold.sweep\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.manifold.Manifold.sweep\">\n<span class=\"sig-name descname\"><span class=\"pre\">sweep</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">n_points</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">64</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">n_stations</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Section boundaries swept into machine coordinates.</p><p>The machine axis is <code class=\"docutils literal notranslate\"><span class=\"pre\">z</span></code> and the dead point sits at azimuth zero. A\nsplit manifold is swept over the whole ring, both branches together, so\nwhat comes back is the closed cavity rather than half of it.</p><p><code class=\"docutils literal notranslate\"><span class=\"pre\">n_points</span></code> samples each boundary piece of the section; <code class=\"docutils literal notranslate\"><span class=\"pre\">n_stations</span></code>\nasks for a finer grid along the branch than the law was resolved on,\nfor drawing \u2013 see <a class=\"reference internal\" href=\"#pyskyfire.ducts.manifold.Manifold.display_geometry\" title=\"pyskyfire.ducts.manifold.Manifold.display_geometry\"><code class=\"xref py py-meth docutils literal notranslate\"><span class=\"pre\">display_geometry()</span></code></a>.</p></dd>", "a[href=\"#module-pyskyfire.ducts.manifold\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire.ducts.manifold<a class=\"headerlink\" href=\"#module-pyskyfire.ducts.manifold\" title=\"Link to this heading\">\u00b6</a></h1><p>A ring that shares flow out to a circumference, or gathers it back in.</p><p>Where a volute collects swirling flow and is sized to conserve the angular\nmomentum it takes in, a manifold has no swirl to conserve. Fluid arrives\nthrough a port and has to travel round to reach the far channels, or comes in\nall round and has to travel to the port; either way the circumferential velocity\nis a cost rather than a design variable. So a manifold is not a volute with a\ndifferent area law, and it is not named the way one is.</p>", "a[href=\"#classes\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Classes<a class=\"headerlink\" href=\"#classes\" title=\"Link to this heading\">\u00b6</a></h2>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 600, interactive: false,
                onShow(instance) {MathJax.typesetPromise([instance.popper]).then(() => {});},
            });
        };
    };
    console.log("tippy tips loaded!");
};
